const items = $input.all();
const wh = $('Webhook PDF').first();
const proyecto = (wh.json.body && wh.json.body.proyecto) || 'default';
const archivo = (wh.binary && wh.binary.data && wh.binary.data.fileName) || 'documento.pdf';
const path_original = (wh.json.body && wh.json.body.path_original) || '';

const CHUNK_SIZE = 1000;
const OVERLAP = 200;
const chunks = [];

for (const item of items) {
  const text = item.json.text || '';
  const numpages = item.json.numpages || 1;
  let i = 0, chunkIndex = 0;
  while (i < text.length) {
    const end = Math.min(i + CHUNK_SIZE, text.length);
    const pagina_aprox = Math.floor((i / Math.max(text.length, 1)) * numpages) + 1;
    chunks.push({
      json: {
        id: `${proyecto}__${archivo}__chunk_${chunkIndex}`,
        text: text.slice(i, end),
        metadata: { archivo, proyecto, tipo: 'pdf', chunk_index: chunkIndex, char_start: i, char_end: end, pagina_aprox, total_paginas: numpages, path_original }
      }
    });
    chunkIndex++;
    if (end >= text.length) break;
    i += CHUNK_SIZE - OVERLAP;
  }
}
return chunks;

const items = $input.all();
return [{ json: {
  texts: items.map(i => i.json.text),
  items: items.map(i => i.json)
}}];

const res = $input.first().json;
const items = $('Prep batch embeddings').first().json.items;
if (!res.data || res.data.length !== items.length) {
  throw new Error(`Embedding count mismatch: got ${res.data?.length}, expected ${items.length}. OpenRouter response: ${JSON.stringify(res).slice(0,300)}`);
}
return items.map((item, i) => ({ json: { ...item, embedding: res.data[i].embedding } }));

const items = $input.all();
return [{ json: {
  ids: items.map(i => i.json.id),
  embeddings: items.map(i => i.json.embedding),
  documents: items.map(i => i.json.text),
  metadatas: items.map(i => i.json.metadata),
}}];
